function buildQuestions(words,limit){const pool=(words||[]).filter(w=>w&&w.word&&w.meaning);return pool.slice(0,Math.min(limit,pool.length)).map((w,idx)=>{let opts=[{text:w.meaning,correct:true},...pool.filter(x=>x.word!==w.word).slice(0,3).map(x=>({text:x.meaning,correct:false}))];const fallbacks=['A different meaning','An unrelated action','Something that happens rarely'];while(opts.length<4)opts.push({text:fallbacks[(opts.length-1)%fallbacks.length],correct:false});opts=opts.slice(0,4);for(let i=opts.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[opts[i],opts[j]]=[opts[j],opts[i]];}return {word:w.word,q:'What does “'+w.word+'” mean?',options:opts.map(o=>o.text),answer:opts.findIndex(o=>o.correct)};});}
