async function initAuth(){try{if(window.hatchable?.auth){const s=await window.hatchable.auth.getSession();state.user=s?.user||null;}}catch(e){console.warn('Auth unavailable',e);}if(state.user){$('#account-email').textContent=state.user.email||'Signed in';$('#login-btn').classList.add('hidden');$('#signout').classList.remove('hidden');await loadOverview();}else{$('#account-email').textContent='Sign in to sync progress';$('#login-btn').classList.remove('hidden');$('#signout').classList.add('hidden');}}
$('#journal-form').onsubmit=submitJournal;$('#refresh-journal-history').onclick=loadJournalHistory;$('#refresh-vocabulary-history').onclick=loadVocabularyHistory;$('#login-btn').onclick=()=>location.href='/login?next=/';$('#signout').onclick=async()=>{try{await window.hatchable.auth.signOut();state.user=null;location.reload();}catch(e){toast('Could not sign out. Please try again.');}};$('#start-learning').onclick=()=>$('#topics-section').scrollIntoView({behavior:'smooth'});$('#view-all-topics').onclick=()=>setView('topics');$('#random-topic').onclick=()=>{const options=state.topics.filter(t=>t.id!==state.topic?.id);const chosen=options[Math.floor(Math.random()*options.length)]||state.topics[0];if(chosen)startSession(chosen.id);};$('#choose-topic').onclick=()=>setView('topics');$('#topics-back-home').onclick=()=>setView('home');$('#back-to-topics').onclick=()=>setView('topics');$('#detail-back-home').onclick=()=>setView('home');$$('.nav-item').forEach(b=>b.onclick=()=>setView(b.dataset.view));
(async()=>{await initAuth();await loadTopics();renderEmpty();if(state.user)await loadOverview();})();